#!/usr/bin/env bash
set -euo pipefail
source "$(dirname "$0")/common.sh"
allow=false; [ "${1:-}" = --allow-duplicate ] && { allow=true; shift; }
alias=${1:?usage: start-destiny.sh [--allow-duplicate] <runtime>}; runtime=$(require_runtime "$alias")
win_ps "\$root=$(ps_quote "$runtime"); \$exe=Join-Path \$root $(ps_quote "$LEGION_DESTINY_EXE_RELATIVE"); if (!(Test-Path -LiteralPath \$root -PathType Container)) { Write-Error 'RUNTIME_EXISTS=FAIL'; exit 2 }; if (!(Test-Path -LiteralPath \$exe -PathType Leaf)) { Write-Error 'DESTINY_EXECUTABLE=FAIL'; exit 3 }; \$running=@(Get-CimInstance Win32_Process -Filter \"Name='destiny2.exe'\" -ErrorAction SilentlyContinue); if (\$running.Count -gt 0 -and '$(printf '%s' "$allow")' -ne 'true') { Write-Error ('duplicate Destiny refusal; existing PIDs=' + ((\$running | ForEach-Object {\$_.ProcessId}) -join ',')); exit 4 }; \$shell=@(Get-CimInstance Win32_Process -Filter \"Name='explorer.exe'\" -ErrorAction SilentlyContinue | Sort-Object SessionId | Select-Object -First 1); if (\$shell.Count -ne 1) { Write-Error 'INTERACTIVE_SESSION=NONE'; exit 5 }; \$owner=Invoke-CimMethod -InputObject \$shell[0] -MethodName GetOwner; if ([string]::IsNullOrWhiteSpace(\$owner.User)) { Write-Error 'INTERACTIVE_SESSION_OWNER=UNKNOWN'; exit 6 }; \$identity=\$owner.Domain + '\\' + \$owner.User; \$runId=Get-Date -Format 'yyyyMMddTHHmmssfff'; \$taskName='OldSchoolD2Lab-' + \$runId; \$action=New-ScheduledTaskAction -Execute \$exe -WorkingDirectory \$root; \$principal=New-ScheduledTaskPrincipal -UserId \$identity -LogonType Interactive -RunLevel Limited; \$task=New-ScheduledTask -Action \$action -Principal \$principal; Register-ScheduledTask -TaskName \$taskName -InputObject \$task -Force | Out-Null; Start-ScheduledTask -TaskName \$taskName; Start-Sleep -Seconds 3; \$started=@(Get-CimInstance Win32_Process -Filter \"Name='destiny2.exe'\" -ErrorAction SilentlyContinue | Where-Object { \$_.SessionId -eq \$shell[0].SessionId -and \$_.ExecutablePath -eq \$exe }); if (\$started.Count -eq 0) { \$info=Get-ScheduledTaskInfo -TaskName \$taskName -ErrorAction SilentlyContinue; Unregister-ScheduledTask -TaskName \$taskName -Confirm:\$false -ErrorAction SilentlyContinue; Write-Error ('PROCESS_START=FAIL;TASK_RESULT=' + \$info.LastTaskResult); exit 7 }; New-Item -ItemType Directory -Force -Path (Join-Path \$root '.lab-control-state') | Out-Null; @{pid=\$started[0].ProcessId; runtime='$(printf '%s' "$alias")'; executable=\$exe; task_name=\$taskName; interactive_session_id=\$shell[0].SessionId; started_utc=[DateTime]::UtcNow.ToString('o')} | ConvertTo-Json -Compress | Set-Content -LiteralPath (Join-Path \$root '.lab-control-state\\started-destiny.json') -Encoding UTF8; Write-Output 'PROCESS_START=PASS'; Write-Output ('DESTINY_PID=' + \$started[0].ProcessId); Write-Output ('INTERACTIVE_SESSION_ID=' + \$shell[0].SessionId); Write-Output ('INTERACTIVE_OWNER=' + \$identity); Write-Output 'LAUNCH_CONTEXT=interactive-task'; Write-Output 'INTERACTIVE_CONTROL_VERIFIED=NO'; Write-Output 'UI_STATE=unknown'; Write-Output 'GAME_TEST_STARTED=NO'"
